const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['會員大會臨時動議可以提嗎','臨時動議'],['開會的時候臨時要提案可以嗎','臨時動議'],['大會當天現場提案算不算數','臨時動議'],['可不可以當天再提新的議案','臨時動議'],
['會員可以委託別人去開會員大會嗎','代理一人'],['一個人最多可以代幾個人出席','最多只能代理一位'],['一人可以接幾個委託書','最多代理一人'],
['開會到一半人走光了還算數嗎','清查'],['大會開一開有人跑掉了怎麼辦','清查'],
['開完大會要不要報給縣府','30日內'],['開完會員大會要不要通知縣府','30日內'],
['大會有沒有規定一定要開在幾月','每年召開一次'],['會員大會是不是一定要在三月開','每年召開一次'],
['會議記錄要多久內寄給會員','查閱'],['會議紀錄要不要發給每個會員','查閱'],
['大會可以用投票箱無記名投票嗎','可以'],['選舉可以用投票箱嗎','可以'],
['會員對大會決議有意見能不能告','律師'],['會員可以去法院告大會的決議嗎','律師'],
['大會表決一定要舉手嗎','不一定要舉手'],
];
const no=['合作社社員大會可以委託別人嗎','公會理監事會議可以委託別人去開嗎','臨時動議可以修改章程嗎','會議紀錄要給會員簽名嗎','合作社開完大會要報縣府嗎','協會解散大會開到一半人走光了','大會選舉可以用舉手嗎'];
const pat=/大會的臨時動議|每位會員最多只能代理一位|開會中途有人離席|開完會員大會要報縣府|沒有規定一定要在哪個月|法規沒有要求寄給會員|可以，而且選舉理事|對大會決議有意見：可以書面/;
let bad=0;
for(const [q,k] of yes){const x=A(q);if(!x||(!x.direct&&!['大會表決一定要舉手嗎','一人可以接幾個委託書'].includes(q))||!(x.summary+x.title).includes(k)){console.error('FAIL',q,x&&x.title);bad++;}}
for(const q of no){const x=A(q);if(x&&typeof x==='object'&&pat.test(x.title)){console.error('OVERTRIGGER',q,x.title);bad++;}}
if(bad)throw new Error('patrol61 failed '+bad);console.log('ok');
